#include <stdio.h>

#define MAX 500

int main(void) {
    int N, M;
    if (scanf("%d %d", &N, &M) != 2) return 0;

    char grid[MAX][MAX + 1];
    int queue[MAX * MAX];
    int head = 0, tail = 0;

    for (int i = 0; i < N; i++) {
        scanf("%s", grid[i]);
        for (int j = 0; j < M; j++) {
            if (grid[i][j] == 'o')
                queue[tail++] = i * M + j;
        }
    }

    while (head < tail) {
        int pos = queue[head++];
        int r = pos / M;
        int c = pos % M;

        if (r + 1 < N) {
            if (grid[r + 1][c] == '.') {
                grid[r + 1][c] = 'o';
                queue[tail++] = (r + 1) * M + c;
            }

            if (grid[r + 1][c] == '#') {
                if (c > 0 && grid[r][c - 1] == '.') {
                    grid[r][c - 1] = 'o';
                    queue[tail++] = r * M + c - 1;
                }
                if (c + 1 < M && grid[r][c + 1] == '.') {
                    grid[r][c + 1] = 'o';
                    queue[tail++] = r * M + c + 1;
                }
            }
        }
    }

    for (int i = 0; i < N; i++)
        printf("%s\n", grid[i]);

    return 0;
}
